function closestClockGap(times: string[]): number {
  const m = times.map(t => Number(t.slice(0, 2)) * 60 + Number(t.slice(3)));
  let best = 1440;
  for (let i = 0; i < m.length; i++)
    for (let j = i + 1; j < m.length; j++) {
      const d = Math.abs(m[i] - m[j]);
      best = Math.min(best, d, 1440 - d);
    }
  return best;
}

