function closestClockGap(times: string[]): number {
  if (times.length > 1440) return 0;
  const seen = new Uint8Array(1440);
  for (const t of times) {
    const v = Number(t.slice(0, 2)) * 60 + Number(t.slice(3));
    if (seen[v]) return 0;
    seen[v] = 1;
  }
  let first = -1, prev = -1, best = 1440;
  for (let v = 0; v < 1440; v++) {
    if (!seen[v]) continue;
    if (first < 0) first = v;
    else best = Math.min(best, v - prev);
    prev = v;
  }
  return Math.min(best, first + 1440 - prev);
}

